using System.Diagnostics;
using ZennoLab.InterfacesLibrary.Enums.Log;
using Newtonsoft.Json;
using Newtonsoft.Json.Linq;
using System.Net;
using z3n7.Api;
using z3n7;
using z3n7.Tools;
using z3n7.Captcha;

OwnCodeUsings.CommonCode:
using System;
using System.Collections.Generic;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Text.RegularExpressions;
using System.Threading;

using ZennoLab.InterfacesLibrary.ProjectModel;
using ZennoLab.CommandCenter;
using ZennoLab.InterfacesLibrary.Enums.Log;

namespace z3n7.Api
{
    /// <summary>
    /// Клиент SMS-провайдера Simroute (handler_api).
    /// Endpoint: GET {base}/stubs/handler_api.php?api_key=...&amp;action=...
    /// Повторяет контракт NumlexNum: те же перегрузки и те же project-переменные
    /// (numId, numPhone, numIssued, numCountry, numCountryCode, numNoCountryCode, numProvider, numDirection).
    /// </summary>
    public class SimrouteNum
    {
        public const int StatusReady = 1;
        public const int StatusRetry = 3;
        public const int StatusFinish = 6;
        public const int StatusCancel = 8;

        private static readonly object RndLock = new object();
        private static readonly Random Rnd = new Random();
        private static readonly string[] JsonHeaders = { "Accept: application/json" };

        private readonly IZennoPosterProjectModel _project;
        private readonly string _endpoint;
        private readonly string _apiKey;
        private readonly SimrouteRoute[] _routes;
        private readonly string _site;

        /// <param name="project">Проект ZennoPoster</param>
        /// <param name="instance">Не используется, оставлен для совместимости с NumlexNum</param>
        /// <param name="apikey">Переопределяет SIMROUTE_API_KEY из .env</param>
        /// <param name="routesPath">Переопределяет SIMROUTE_ROUTES_PATH из .env</param>
        public SimrouteNum(
            IZennoPosterProjectModel project,
            Instance instance = null,
            string apikey = null,
            string routesPath = null)
        {
            _project = project ?? throw new ArgumentNullException(nameof(project));
            _site = project.Var("site");

            var baseUrl = project.ReadEnv("SIMROUTE_BASE_URL");
            if (string.IsNullOrWhiteSpace(baseUrl))
                throw new Exception("z3n7.Simroute SIMROUTE_BASE_URL is not set in .env");

            _endpoint = BuildEndpoint(baseUrl);

            _apiKey = string.IsNullOrWhiteSpace(apikey)
                ? project.ReadEnv("SIMROUTE_API_KEY")
                : apikey;

            if (string.IsNullOrWhiteSpace(_apiKey))
                throw new Exception("z3n7.Simroute SIMROUTE_API_KEY is not set in .env");

            var path = string.IsNullOrWhiteSpace(routesPath)
                ? project.ReadEnv("SIMROUTE_ROUTES_PATH")
                : routesPath;

            _routes = LoadRoutes(path);
        }

        private static string BuildEndpoint(string baseUrl)
        {
            baseUrl = baseUrl.Trim().TrimEnd('/');

            if (baseUrl.IndexOf("handler_api.php", StringComparison.OrdinalIgnoreCase) >= 0)
                return baseUrl;

            return baseUrl + "/stubs/handler_api.php";
        }

        #region GetNumber

        /// <summary>
        /// Получить номер по service + country.
        /// Возвращает [activationId, phone].
        /// Дополнительно сохраняет:
        /// numCountry, numCountryCode, numNoCountryCode, numProviderId, numOperator.
        /// </summary>
        public string[] GetNumber(string service, int country, string poolName = null, string providerId = null)
        {
            if (string.IsNullOrWhiteSpace(service))
                throw new ArgumentException("service is empty", nameof(service));

            var route = _routes.FirstOrDefault(x => x.CountryId == country);
            var countryAlias = route?.CountryIso;

            if (string.IsNullOrWhiteSpace(countryAlias))
                countryAlias = country.ToString(CultureInfo.InvariantCulture);

            _project.Var("numDirection", countryAlias + "-" + service);

            var url = Url("getNumber")
                      + "&service=" + Uri.EscapeDataString(service)
                      + "&country=" + country.ToString(CultureInfo.InvariantCulture);

            if (!string.IsNullOrWhiteSpace(poolName))
                url += "&pool_name=" + Uri.EscapeDataString(poolName);

            if (!string.IsNullOrWhiteSpace(providerId))
                url += "&provider=" + Uri.EscapeDataString(providerId);

            var retry = 10;
            string error = null;

            while (retry-- > 0)
            {
                _project.Var("numAttempts", (10 - retry).ToString(CultureInfo.InvariantCulture));

                var response = Call(url);
                _project.Var("numStatus", response.Head);

                if (response.Head == "ACCESS_NUMBER")
                {
                    var number = Remember(response, route, service, country);
                    _project.SendInfoToLog($"using {_project.Var("numDirection")}", true);
                    return number;
                }

                error = response.Describe();

                // NO_NUMBERS / CHANNELS_LIMIT рассасываются сами, остальное — нет
                if (response.Head != "NO_NUMBERS" && response.Head != "CHANNELS_LIMIT")
                    break;

                Thread.Sleep(3000);
            }

            _project.SendWarningToLog(error + $" on {_project.Var("numDirection")}", true);
            _project.Var("err", error);
            throw new Exception(error);
        }

        public string[] GetNumber(string service, string countryName)
        {
            if (string.IsNullOrWhiteSpace(service))
                throw new ArgumentException("service is empty", nameof(service));

            if (string.IsNullOrWhiteSpace(countryName))
                throw new ArgumentException("countryName is empty", nameof(countryName));

            var countryKey = NormalizeKey(countryName);

            var route = _routes.FirstOrDefault(x =>
                x.Service.Equals(service, StringComparison.OrdinalIgnoreCase) &&
                x.HasCountryName(countryKey));

            if (route == null)
                throw new Exception($"z3n7.Simroute route not found: {countryName}-{service}");

            return GetNumber(route.Service, route.CountryId);
        }

        public string[] GetNumber(int country)
        {
            var route = PickRouteByCountryId(country);

            if (route == null)
                throw new Exception($"z3n7.Simroute country not found in Routes: {country}");

            return GetNumber(route.Service, route.CountryId);
        }

        public string[] GetNumber(string countryName)
        {
            if (string.IsNullOrWhiteSpace(countryName))
                throw new ArgumentException("countryName is empty", nameof(countryName));

            if (countryName.Contains(","))
            {
                var countries = countryName.Split(',');
                lock (RndLock)
                    countryName = countries[Rnd.Next(countries.Length)].Trim();
            }

            var route = PickRouteByCountryName(countryName);

            if (route == null)
                throw new Exception($"z3n7.Simroute country not found in Routes: {countryName}");

            return GetNumber(route.Service, route.CountryId);
        }

        public void GetNumberByProxy(string service = null)
        {
            var rnd = _project.Int("varRnd");
            var prx = NormalizeKey(_project.Var("proxy_location"));
            var availableRoutes = new List<SimrouteRoute>();

            for (int i = 0; i < _routes.Length; i++)
            {
                if (NormalizeKey(_routes[i].CountryIso) == prx)
                    availableRoutes.Add(_routes[i]);
            }

            if (availableRoutes.Count == 0)
                throw new Exception("Provider not found for proxy location: " + prx);

            var route = availableRoutes[Math.Abs(rnd) % availableRoutes.Count];

            var s = string.IsNullOrWhiteSpace(service) ? route.Service : service;

            GetNumber(s, route.CountryId);
        }

        private string[] Remember(SimrouteResponse response, SimrouteRoute route, string service, int country)
        {
            var id = response.Value("activationId");
            var phone = response.Value("phone");

            if (string.IsNullOrWhiteSpace(id) || string.IsNullOrWhiteSpace(phone))
                throw new Exception("z3n7.Simroute ACCESS_NUMBER without id/phone: " + response.Raw);

            var countryCode = route?.CountryCode ?? "";
            var noCountryCode = phone;

            if (!string.IsNullOrWhiteSpace(countryCode))
            {
                var digits = countryCode.TrimStart('+');

                if (phone.TrimStart('+').StartsWith(digits, StringComparison.Ordinal))
                    noCountryCode = phone.TrimStart('+').Substring(digits.Length);
            }

            _project.Var("numId", id);
            _project.Var("numPhone", phone);
            _project.Var("numIssued", DateTimeOffset.UtcNow.ToUnixTimeMilliseconds().ToString());
            _project.Var("numCountry", route?.CountryName ?? country.ToString(CultureInfo.InvariantCulture));
            _project.Var("numCountryCode", countryCode);
            _project.Var("numNoCountryCode", noCountryCode);
            _project.Var("numProvider", service);
            _project.Var("numProviderId", response.Value("providerId") ?? "");
            _project.Var("numOperator", response.Value("operatorName") ?? "");

            return new[] { id, phone };
        }

        #endregion

        #region Sms

        /// <summary>
        /// Ждать SMS-код по текущему numId.
        /// </summary>
        /// <param name="deadline">Таймаут ожидания, сек</param>
        /// <param name="previous">Код предыдущей активации — если придёт он же, ждём дальше</param>
        public string GetSms(int deadline = 180, string previous = null)
        {
            var id = _project.Var("numId");

            if (string.IsNullOrWhiteSpace(id))
                throw new Exception("z3n7.Simroute numId is empty, call GetNumber first");

            var d = new Time.Deadline();
            var url = Url("getStatus") + "&id=" + Uri.EscapeDataString(id);

            while (true)
            {
                Thread.Sleep(5000);

                try
                {
                    d.Check(deadline);
                }
                catch (TimeoutException)
                {
                    _project.Var("err", $"no sms in {deadline}s");
                    throw;
                }

                var age = _project.Age<string>("numIssued");
                var response = Call(url);
                _project.Var("smsStatus", response.Head);

                // STATUS_OK:1234 / STATUS_WAIT_CODE:1234 / STATUS_WAIT_RETRY:1234
                var smsCode = response.Value("code") ?? response.Tail;

                if (!string.IsNullOrWhiteSpace(smsCode))
                {
                    if (!string.IsNullOrWhiteSpace(previous) && smsCode == previous)
                        continue;

                    _project.SendToLog(
                        $" received {smsCode} for {_site} on {_project.Var("numDirection")}. Took {age.Substring(3, 5)}m",
                        LogType.Info, true, LogColor.Blue);

                    return smsCode;
                }

                if (response.Head == "STATUS_WAIT_CODE" || response.Head == "STATUS_WAIT_RETRY")
                {
                    _project.SendInfoToLog(
                        $" waiting sms for {_site} on {_project.Var("numDirection")}. elapsed {age.Substring(3, 5)}",
                        true);
                    continue;
                }

                var error = response.Describe();
                _project.Var("err", error);
                _project.warn(error);
                throw new Exception(error);
            }
        }

        /// <summary>
        /// Ждать полный текст SMS (все сообщения активации).
        /// Требует включённой настройки fullSms на стороне провайдера.
        /// </summary>
        public string GetFullSms(int deadline = 180)
        {
            var id = _project.Var("numId");

            if (string.IsNullOrWhiteSpace(id))
                throw new Exception("z3n7.Simroute numId is empty, call GetNumber first");

            var d = new Time.Deadline();
            var url = Url("getFullSms") + "&id=" + Uri.EscapeDataString(id);

            while (true)
            {
                Thread.Sleep(5000);
                d.Check(deadline);

                var age = _project.Age<string>("numIssued");
                var response = Call(url);

                if (response.Head == "FULL_SMS")
                {
                    var text = response.Value("text") ?? response.Tail ?? "";

                    _project.SendToLog(
                        $" received sms for {_site} on {_project.Var("numDirection")}. Took {age.Substring(3, 5)}m",
                        LogType.Info, true, LogColor.Blue);

                    return text;
                }

                if (response.Head == "STATUS_WAIT_CODE" || response.Head == "STATUS_WAIT_RETRY")
                {
                    _project.SendInfoToLog(
                        $" waiting sms for {_site} on {_project.Var("numDirection")}. elapsed {age.Substring(3, 5)}",
                        true);
                    continue;
                }

                var error = response.Describe();
                _project.warn(error);
                throw new Exception(error);
            }
        }

        #endregion

        #region SetStatus

        /// <summary>Завершить активацию успешно (status=6).</summary>
        public void SmsSent()
        {
            SetStatus(StatusFinish);
        }

        /// <summary>Отменить активацию (status=8).</summary>
        public void Cancel()
        {
            SetStatus(StatusCancel);
        }

        /// <summary>Запросить повторную отправку SMS (status=3).</summary>
        public void Retry()
        {
            SetStatus(StatusRetry);
        }

        /// <summary>Сообщить, что номер готов принимать SMS (status=1).</summary>
        public void Ready()
        {
            SetStatus(StatusReady);
        }

        public string SetStatus(int status)
        {
            var id = _project.Var("numId");

            if (string.IsNullOrWhiteSpace(id))
                throw new Exception("z3n7.Simroute numId is empty, call GetNumber first");

            var url = Url("setStatus")
                      + "&id=" + Uri.EscapeDataString(id)
                      + "&status=" + status.ToString(CultureInfo.InvariantCulture);

            var response = Call(url);

            if (response.Head == "ACCESS_ACTIVATION" ||
                response.Head == "ACCESS_CANCEL" ||
                response.Head == "ACCESS_RETRY_GET" ||
                response.Head == "ACCESS_READY")
                return response.Status;

            var error = response.Describe();
            _project.warn(error);
            throw new Exception(error);
        }

        #endregion

        #region Account

        /// <summary>Текущий баланс.</summary>
        public decimal Balance()
        {
            var response = Call(Url("getBalance"));

            if (response.Head != "ACCESS_BALANCE")
                throw new Exception(response.Describe());

            var raw = response.Value("amount") ?? response.Tail;

            if (!decimal.TryParse(raw, NumberStyles.Any, CultureInfo.InvariantCulture, out var amount))
                throw new Exception("z3n7.Simroute bad balance: " + response.Raw);

            return amount;
        }

        /// <summary>Доступное количество одновременных активаций. long.MaxValue = без лимита.</summary>
        public long Concurrency(string service, int country, string providerId = null)
        {
            var url = Url("getConcurrency")
                      + "&service=" + Uri.EscapeDataString(service)
                      + "&country=" + country.ToString(CultureInfo.InvariantCulture);

            if (!string.IsNullOrWhiteSpace(providerId))
                url += "&provider=" + Uri.EscapeDataString(providerId);

            var response = Call(url);
            var raw = response.Value("available") ?? response.Raw.Trim();

            if (!long.TryParse(raw, NumberStyles.Any, CultureInfo.InvariantCulture, out var available))
                throw new Exception(response.Describe());

            return available;
        }

        /// <summary>Сырой JSON цен: { "{countryId}": { "{service}": { price, count, physicalCount } } }.</summary>
        public string GetPrices(string service = null, int? country = null)
        {
            var url = Url("getPrices");

            if (!string.IsNullOrWhiteSpace(service))
                url += "&service=" + Uri.EscapeDataString(service);

            if (country.HasValue)
                url += "&country=" + country.Value.ToString(CultureInfo.InvariantCulture);

            return _project.GET(url, headers: JsonHeaders, log: false, thrw: true);
        }

        /// <summary>Сырой JSON пулов. Требует включённой настройки poolAccess.</summary>
        public string GetPools(string service, int country, string providerId = null)
        {
            var url = Url("getPools")
                      + "&service=" + Uri.EscapeDataString(service)
                      + "&country=" + country.ToString(CultureInfo.InvariantCulture);

            if (!string.IsNullOrWhiteSpace(providerId))
                url += "&provider=" + Uri.EscapeDataString(providerId);

            return _project.GET(url, headers: JsonHeaders, log: false, thrw: true);
        }

        /// <summary>Секунд с момента выдачи номера.</summary>
        public long Elapsed()
        {
            long elapsedSeconds =
                (DateTimeOffset.UtcNow.ToUnixTimeMilliseconds() - long.Parse(_project.Var("numIssued"))) / 1000;
            return elapsedSeconds;
        }

        #endregion

        #region Transport

        private string Url(string action)
        {
            return _endpoint
                   + "?api_key=" + Uri.EscapeDataString(_apiKey)
                   + "&action=" + Uri.EscapeDataString(action);
        }

        private SimrouteResponse Call(string url)
        {
            var raw = _project.GET(url, headers: JsonHeaders, log: false, thrw: true);
            _project.Var("numRaw", raw);
            return SimrouteResponse.Parse(raw);
        }

        /// <summary>
        /// Ответ handler_api в обоих форматах: JSON ({"status":"...","code":"..."})
        /// и text ("STATUS_OK:1234", "ACCESS_NUMBER:id:phone:providerId:operatorName").
        /// </summary>
        private class SimrouteResponse
        {
            /// <summary>Полное значение status, как пришло ("STATUS_WAIT_CODE:1111").</summary>
            public string Status { get; private set; }

            /// <summary>Status до первого двоеточия ("STATUS_WAIT_CODE").</summary>
            public string Head { get; private set; }

            /// <summary>Хвост после первого двоеточия, если он есть ("1111"), иначе null.</summary>
            public string Tail { get; private set; }

            public string Raw { get; private set; }

            private Newtonsoft.Json.Linq.JObject _json;
            private string[] _parts;

            public static SimrouteResponse Parse(string raw)
            {
                var result = new SimrouteResponse { Raw = raw ?? "" };
                var trimmed = result.Raw.Trim();

                if (trimmed.StartsWith("{", StringComparison.Ordinal))
                {
                    try
                    {
                        result._json = Newtonsoft.Json.Linq.JObject.Parse(trimmed);
                        result.SetStatus(result._json["status"]?.ToString() ?? "");
                        return result;
                    }
                    catch (Newtonsoft.Json.JsonException)
                    {
                        result._json = null;
                    }
                }

                result._parts = trimmed.Split(':');
                result.SetStatus(trimmed);
                return result;
            }

            private void SetStatus(string status)
            {
                Status = status ?? "";

                var colon = Status.IndexOf(':');

                if (colon < 0)
                {
                    Head = Status;
                    Tail = null;
                    return;
                }

                Head = Status.Substring(0, colon);
                var tail = Status.Substring(colon + 1).Trim();
                Tail = tail.Length == 0 ? null : tail;
            }

            /// <summary>
            /// Значение поля: из JSON по имени, из text — по позиции в "ACCESS_NUMBER:...".
            /// </summary>
            public string Value(string name)
            {
                if (_json != null)
                {
                    var token = _json[name];

                    if (token == null || token.Type == Newtonsoft.Json.Linq.JTokenType.Null)
                        return null;

                    var value = token.ToString();
                    return value.Length == 0 ? null : value;
                }

                var index = TextIndex(name);

                if (index < 0 || _parts == null || _parts.Length <= index)
                    return null;

                var part = _parts[index].Trim();
                return part.Length == 0 ? null : part;
            }

            private int TextIndex(string name)
            {
                // ACCESS_NUMBER:ACTIVATION_ID:PHONE:PROVIDER_ID:OPERATOR_NAME
                if (Head != "ACCESS_NUMBER")
                    return -1;

                switch (name)
                {
                    case "activationId": return 1;
                    case "phone": return 2;
                    // providerId и operatorName опциональны и оба занимают 4-ю позицию,
                    // различаем по тому, число это или нет
                    case "providerId": return IsNumeric(3) ? 3 : -1;
                    case "operatorName": return IsNumeric(3) ? 4 : 3;
                    default: return -1;
                }
            }

            private bool IsNumeric(int index)
            {
                if (_parts == null || _parts.Length <= index)
                    return false;

                return long.TryParse(_parts[index].Trim(), out _);
            }

            /// <summary>Человекочитаемое описание ошибки для лога/исключения.</summary>
            public string Describe()
            {
                var reason = Value("reason");

                if (string.IsNullOrWhiteSpace(reason))
                    return string.IsNullOrWhiteSpace(Status) ? Raw : Status;

                return Status + " (" + reason + ")";
            }
        }

        #endregion

        #region Routes

        private SimrouteRoute PickRouteByCountryId(int countryId)
        {
            var list = new List<SimrouteRoute>();

            for (int i = 0; i < _routes.Length; i++)
            {
                if (_routes[i].CountryId == countryId)
                    list.Add(_routes[i]);
            }

            return PickRandom(list);
        }

        private SimrouteRoute PickRouteByCountryName(string countryName)
        {
            var list = new List<SimrouteRoute>();
            string key = NormalizeKey(countryName);

            for (int i = 0; i < _routes.Length; i++)
            {
                if (_routes[i].HasCountryName(key))
                    list.Add(_routes[i]);
            }

            return PickRandom(list);
        }

        private static SimrouteRoute PickRandom(List<SimrouteRoute> list)
        {
            if (list == null || list.Count == 0)
                return null;

            lock (RndLock)
            {
                return list[Rnd.Next(list.Count)];
            }
        }

        private static string NormalizeKey(string value)
        {
            if (string.IsNullOrEmpty(value))
                return "";

            value = value.Trim().ToLowerInvariant();

            var chars = new List<char>();

            for (int i = 0; i < value.Length; i++)
            {
                char c = value[i];

                if (c == ' ' || c == '-' || c == '_' || c == '.')
                    continue;

                chars.Add(c);
            }

            return new string(chars.ToArray());
        }

        private class SimrouteRoute
        {
            public readonly string CountryName;
            public readonly int CountryId;
            public readonly string Service;
            public readonly string CountryCode;
            public readonly string CountryIso;

            private readonly string[] _aliases;

            public SimrouteRoute(
                string countryName,
                int countryId,
                string service,
                string countryCode,
                params string[] aliases)
            {
                CountryName = countryName;
                CountryId = countryId;
                Service = service;
                CountryCode = countryCode;

                var list = new List<string> { countryName };

                if (aliases != null)
                {
                    for (int i = 0; i < aliases.Length; i++)
                        list.Add(aliases[i]);
                }

                _aliases = list.ToArray();
                CountryIso = FindCountryIso(_aliases);
            }

            public bool HasCountryName(string normalizedName)
            {
                for (int i = 0; i < _aliases.Length; i++)
                {
                    if (NormalizeKey(_aliases[i]) == normalizedName)
                        return true;
                }

                return false;
            }

            private static string FindCountryIso(string[] aliases)
            {
                if (aliases == null)
                    return "";

                for (int i = 0; i < aliases.Length; i++)
                {
                    if (!string.IsNullOrWhiteSpace(aliases[i]) &&
                        aliases[i].Trim().Length == 2)
                    {
                        return aliases[i].Trim().ToUpperInvariant();
                    }
                }

                return "";
            }
        }

        /// <summary>
        /// routes.json тот же, что у Numlex: [{ country_name, country_id, service, country_code, aliases[] }].
        /// Файл опционален — без него работают только перегрузки с числовым country.
        /// </summary>
        private static SimrouteRoute[] LoadRoutes(string path)
        {
            if (string.IsNullOrWhiteSpace(path))
                return new SimrouteRoute[0];

            if (!File.Exists(path))
                throw new FileNotFoundException("routes.json not found", path);

            string json = File.ReadAllText(path);

            var result = new List<SimrouteRoute>();

            foreach (Match obj in Regex.Matches(json, @"\{[^{}]*\}", RegexOptions.Singleline))
            {
                string block = obj.Value;

                string countryName = JsonString(block, "country_name");
                int countryId = int.Parse(JsonString(block, "country_id"), CultureInfo.InvariantCulture);
                string service = JsonString(block, "service");
                string countryCode = JsonString(block, "country_code");

                var aliases = JsonArray(block, "aliases");

                result.Add(new SimrouteRoute(
                    countryName,
                    countryId,
                    service,
                    countryCode,
                    aliases.ToArray()
                ));
            }

            if (result.Count == 0)
                throw new Exception("routes.json has no routes");

            return result.ToArray();
        }

        private static string JsonString(string block, string name)
        {
            var m = Regex.Match(
                block,
                "\"" + Regex.Escape(name) + "\"\\s*:\\s*(\"(?<s>(?:\\\\.|[^\"])*)\"|(?<n>-?\\d+))",
                RegexOptions.Singleline
            );

            if (!m.Success)
                throw new Exception("routes.json field not found: " + name);

            if (m.Groups["n"].Success)
                return m.Groups["n"].Value;

            return Regex.Unescape(m.Groups["s"].Value);
        }

        private static List<string> JsonArray(string block, string name)
        {
            var result = new List<string>();

            var m = Regex.Match(
                block,
                "\"" + Regex.Escape(name) + "\"\\s*:\\s*\\[(?<items>.*?)\\]",
                RegexOptions.Singleline
            );

            if (!m.Success)
                return result;

            foreach (Match item in Regex.Matches(m.Groups["items"].Value, "\"(?<s>(?:\\\\.|[^\"])*)\""))
                result.Add(Regex.Unescape(item.Groups["s"].Value));

            return result;
        }

        #endregion
    }
}
namespace z3n7
{
    /// <summary>Отчёт SimRoute в локальной SQLite через FastDb. Весь SQL живёт здесь.</summary>
    public static class SimrouteDb
    {
        public const string ResultOk        = "OK";           // номер получен, SMS доставлена
        public const string ResultNoNumber  = "NO_NUMBER";    // номер не получен
        public const string ResultSmsFailed = "SMS_FAILED";   // номер получен, доставки не было

        private const string DbName = "simroute";
        private const string Table  = "simroute_report";

        private static readonly Dictionary<string, string> Structure = new Dictionary<string, string>
        {
            { "id",            "INTEGER PRIMARY KEY AUTOINCREMENT" },
            { "ts_utc",        "TEXT" },
            { "country",       "TEXT DEFAULT ''" },
            { "country_id",    "TEXT DEFAULT ''" },
            { "service",       "TEXT DEFAULT ''" },
            { "service_code",  "TEXT DEFAULT ''" },
            { "attempts",      "INTEGER DEFAULT 0" },
            { "num_status",    "TEXT DEFAULT ''" },
            { "activation_id", "TEXT DEFAULT ''" },
            { "phone_masked",  "TEXT DEFAULT ''" },
            { "sms_code",      "TEXT DEFAULT ''" },
            { "result",        "TEXT DEFAULT ''" },
            { "error",         "TEXT DEFAULT ''" },
            { "api_response",  "TEXT DEFAULT ''" },
        };

        public static void CreateTable(IZennoPosterProjectModel project)
        {
            var columns = string.Join(", ", Structure.Select(x => Quote(x.Key) + " " + x.Value));
            new FastDb(project, DbName).dbString($"CREATE TABLE IF NOT EXISTS {Table} ({columns})");
        }

        /// <summary>Одна строка на активацию. Всё берётся из переменных, заполненных SimrouteNum.</summary>
        public static void Report(IZennoPosterProjectModel project, string result)
        {
            var phone = project.Var("numPhone");

            var row = new Dictionary<string, string>
            {
                { "ts_utc",        DateTime.UtcNow.ToString("yyyy-MM-dd HH:mm:ss") },
                { "country",       project.Var("numCountry") },
                { "country_id",    project.Var("numCountryId") },
                { "service",       project.Var("numServiceName") },
                { "service_code",  project.Var("numProvider") },
                { "attempts",      project.Var("numAttempts") },
                { "num_status",    project.Var("numStatus") },
                { "activation_id", project.Var("numId") },
                { "phone_masked",  Mask(phone) },
                { "sms_code",      project.Var("numSms") },
                { "result",        result },
                { "error",         result == ResultOk ? "" : project.Var("err") },
                { "api_response",  Clean(project.Var("numRaw"), phone) },
            };

            var columns = string.Join(", ", row.Keys.Select(Quote));
            var values  = string.Join(", ", row.Values.Select(Escape));

            new FastDb(project, DbName).dbString($"INSERT INTO {Table} ({columns}) VALUES ({values})");
        }

        public static string ExportCsv(IZennoPosterProjectModel project, string fileName = "simroute_report.csv")
        {
            new FastDb(project, DbName).ExportToCsv(Table, fileName, "*");
            return project.Path + fileName;
        }

        public static string Mask(string phone)
        {
            var d = (phone ?? "").TrimStart('+');

            if (d.Length == 0) return "";
            if (d.Length <= 7) return new string('*', d.Length);

            return "+" + d.Substring(0, 5) + new string('*', d.Length - 7) + d.Substring(d.Length - 2);
        }

        // \n и | — разделители строк и колонок у FastDb, иначе чтение таблицы разъедется
        private static string Clean(string raw, string phone)
        {
            var value = (raw ?? "").Replace("\r", " ").Replace("\n", " ").Replace("|", "/");

            if (!string.IsNullOrEmpty(phone))
                value = value.Replace(phone, Mask(phone));

            return value.Length > 2000 ? value.Substring(0, 2000) : value;
        }

        private static string Quote(string name)   { return "\"" + name + "\""; }
        private static string Escape(string value) { return "'" + (value ?? "").Replace("'", "''") + "'"; }
    }
}

