        + "&id=" + Uri.EscapeDataString(project.Var("numId"))
        + "&api_key=" + Uri.EscapeDataString(project.ReadEnv("SIMROUTE_API_KEY"));

int limit;
if (!int.TryParse(project.Var("smsDeadline"), out limit) || limit < 1) limit = 180;

var until = DateTime.UtcNow.AddSeconds(limit);
string st = "", code = "";

do
{
    var r = project.GET(url, headers: new[] { "Accept: application/json" }, log: false, thrw: false);
    project.Var("numRaw", r);

    st = r ?? ""; code = "";

    if (st.StartsWith("{"))
    {
        try
        {
            var j = JObject.Parse(st);
            st   = j["status"] == null ? "" : j["status"].ToString();
            code = j["code"]   == null ? "" : j["code"].ToString();
        }
        catch { st = "BAD_JSON"; }
    }

    // код может приехать суффиксом внутри статуса: STATUS_OK:1234, STATUS_WAIT_CODE:1234
    var c = st.IndexOf(':');
    if (c > 0) { if (code == "") code = st.Substring(c + 1).Trim(); st = st.Substring(0, c); }

    project.Var("smsStatus", st);
    project.SendInfoToLog("sms poll: " + st + (code == "" ? "" : " code=" + code), true);

    if (code != "")
    {
        project.Var("numSms",    code);
        project.Var("numResult", "OK");
        return code;
    }

    if (st != "STATUS_WAIT_CODE" && st != "STATUS_WAIT_RETRY") break;   // STATUS_CANCEL, NO_ACTIVATION

    Thread.Sleep(5000);
}
while (DateTime.UtcNow < until);

